python3 -c 'import subprocess
cases = [(["2"], "The the CAT cat dog 42", b"cat\t2\nthe\t2\n", 0), (["5"], "123 !?", b"", 0), (["0"], "hello", None, None), (["abc"], "hello", None, None)]
for args, text, expected, expected_code in cases:
    result = subprocess.run(["python3", "topwords.py", *args], input=text.encode("utf-8"), stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if expected is not None:
        assert result.returncode == expected_code and result.stdout == expected, (args, result.returncode, result.stdout)
    else:
        assert result.returncode != 0, (args, result.returncode)'
